use std::process::Command;

/// Executes a system command and returns the output.
///
/// # Arguments
/// * `command` - A string slice that holds the command to run.
/// * `args` - A vector of string slices that hold the arguments for the command.
///
/// # Returns
/// * Result<String, String> - The output of the command or an error message.
pub fn run_command(command: &str, args: &[&str]) -> Result<String, String> {
    let output = Command::new(command)
        .args(args)
        .output()
        .map_err(|e| e.to_string())?;

    if output.status.success() {
        String::from_utf8(output.stdout).map_err(|e| e.to_string())
    } else {
        Err(String::from_utf8_lossy(&output.stderr).to_string())
    }
}

mod executor;

use std::io::{self, BufRead};
use std::net::{TcpListener, TcpStream};
use std::str;

fn handle_client(stream: TcpStream) -> io::Result<()> {
    let reader = io::BufReader::new(stream);
    for line in reader.lines() {
        let command = line?;
        let parts: Vec<&str> = command.split_whitespace().collect();
        let (cmd, args) = parts.split_at(1);
        let result = executor::run_command(cmd[0], args);
        match result {
            Ok(output) => println!("Output: {}", output),
            Err(e) => eprintln!("Error: {}", e),
        }
    }
    Ok(())
}

fn main() -> io::Result<()> {
    let listener = TcpListener::bind("127.0.0.1:4444")?;
    println!("Server listening on 127.0.0.1:4444");
    for stream in listener.incoming() {
        match stream {
            Ok(s) => handle_client(s)?,
            Err(e) => eprintln!("Connection failed: {}", e),
        }
    }
    Ok(())
}
